// === Punktas 4: MnM angliškų tekstų vertimas į LT (JS override) ===
// MnM statusą renderina per savo i18n/JS su placeholder'iais (%v, %s), todėl gettext
// nepatikimas. Vietoj to — JS keičia matomą tekstą DOM'e po kiekvieno MnM atnaujinimo.
add_action('wp_footer', function() {
    if (empty($GLOBALS['petshop_is_choice_page'])) return;
    ?>
    <script>
    (function(){
        function ltTranslate(root){
            root = root || document;
            // 1. Statuso/pranešimų tekstai
            var statusEls = root.querySelectorAll('.mnm_price, .mnm_message, .mnm_status, .cart .quantity_message, .mnm_add_to_cart .mnm_message, .psc-form .mnm_price, .psc-form .mnm_message');
            statusEls.forEach(function(el){
                var t = el.innerHTML;
                if (!t || (t.indexOf('items')<0 && t.indexOf('item')<0 && t.indexOf('select')<0 && t.indexOf('selected')<0)) return;
                var orig = t;
                t = t.replace(/You have selected\s+(\d+)\s+items?\./gi, 'Pasirinkote $1 vnt.');
                t = t.replace(/Please select\s+(\d+)\s+items?\s+to continue/gi, 'Pasirinkite $1 vnt., kad tęstumėte');
                t = t.replace(/Please choose\s+(\d+)\s+items?\s+to continue/gi, 'Pasirinkite $1 vnt., kad tęstumėte');
                t = t.replace(/You can select more or add to cart to continue/gi, 'Galite rinktis daugiau arba įdėti į krepšelį');
                t = t.replace(/Add to cart to continue/gi, 'Įdėkite į krepšelį');
                t = t.replace(/(\d+)\s*\/\s*(\d+)\s+items/gi, '$1/$2 vnt.');
                t = t.replace(/(\d+)\s+items?\b/gi, '$1 vnt.');
                if (t !== orig) el.innerHTML = t;
            });

            // 2. Lentelės antraštės ir kiti fiksuoti MnM UI string'ai (PRODUCT, QUANTITY ir kt.)
            var headerMap = {
                'PRODUCT': 'PREKĖ', 'Product': 'Prekė', 'product': 'prekė',
                'QUANTITY': 'KIEKIS', 'Quantity': 'Kiekis', 'quantity': 'kiekis',
                'PRICE': 'KAINA', 'Price': 'Kaina',
                'Clear': 'Išvalyti', 'Clear selections': 'Išvalyti pasirinkimus',
                'In stock': 'Turime', 'Out of stock': 'Neturime',
                'Add to cart': 'Į krepšelį'
            };
            var headerEls = root.querySelectorAll('.mnm_child_products th, .mnm_table th, th.product-details, th.product-quantity, th.product-price, th.product-name');
            headerEls.forEach(function(el){
                var txt = el.textContent.trim();
                if (headerMap[txt]) el.textContent = headerMap[txt];
            });
        }

        // Vykdom po kiekvieno MnM atnaujinimo
        function hook(){
            ltTranslate(document);
            // MnM trigerina jQuery įvykius
            if (window.jQuery) {
                jQuery(document.body).on('wc-mnm-container-updated wc-mnm-initialize updated_wc_div wc_fragments_refreshed', function(){
                    setTimeout(function(){ ltTranslate(document); }, 50);
                });
                jQuery(document).on('change keyup', '.mnm_child_products input.qty', function(){
                    setTimeout(function(){ ltTranslate(document); }, 100);
                });
            }
            // MutationObserver — VISOMS formoms (matomoms ir paslėptoms)
            document.querySelectorAll('.psc-form, .petshop-choice-constructor').forEach(function(target){
                if (window.MutationObserver) {
                    var obs = new MutationObserver(function(){ ltTranslate(document); });
                    obs.observe(target, {childList:true, subtree:true, characterData:true});
                }
            });
            // Kartotinis vertimas per pirmas sekundes (MnM inicijuoja formas laipsniškai)
            var tries = 0;
            var iv = setInterval(function(){
                ltTranslate(document);
                if (++tries >= 6) clearInterval(iv);
            }, 400);
        }

        if (document.readyState !== 'loading') hook();
        else document.addEventListener('DOMContentLoaded', hook);
        // Papildomai po pilno užkrovimo (MnM inicijuojasi vėlai)
        window.addEventListener('load', function(){ setTimeout(function(){ ltTranslate(document); }, 300); });
    })();
    </script>
    <?php
